gui.widgetTenetItemText:
type widget_tenet_item = widget {
		size = { 130 200 }
		allow_outside = yes

		block "tenet_enabled" {
			enabled = "[Not( Faith.HasTenetStatus( TenetType.Self, 'unknown' ) )]"
		}

		tooltipwidget = {
			using = tenet_type_tooltip
		}
		using = tooltip_es

		using = Tenet_Glows

		highlight_icon = {
			name = "doctrine_group_bg"
			size = { 130 200 }
			texture = "[Faith.GetTenetBackgroundIcon( Rite.Self, TenetType.Self )]"
		}

		block "tenet_icon"
		{
			widget = {
				position = { 0 -10 }
				size = { 130 200 }
				allow_outside = yes
				alwaystransparent = yes
				visible = "[TenetType.IsValid]"

				highlight_icon = {
					name = "doctrine_group_icon"
					widgetanchor = center
					parentanchor = center

					size = { 130 200 }
					texture = "[TenetItem.GetIcon]"
					alpha = 0.85
				}
			}
		}

		block "tenet_add_icon"
		{
			button_plus = {
				name = "doctrine_group_icon"
				visible = "[Not( TenetType.IsValid )]"

				position = { 35 70 }
				size = { 60 60 }
			}
		}

		vbox = {
			layoutpolicy_horizontal = expanding
			layoutpolicy_vertical = expanding

			margin_bottom = 15

			expand = {}

			text_label_center = {
				name = "tenet_name"
				font = MMDragonTenetUpright
				layoutpolicy_horizontal = expanding
				maximumsize = { 130 44 }
				visible = "[TenetType.IsValid]"
				fontsize_min = 12
				multiline = yes
				align = center
				elide = right
				block "tenet_name" {
					text = "[TenetType.GetBaseNameNoTooltip]"
				}
				default_format = "#high"

				using = Font_Size_Medium
			}
		}

		block "prohibited_warning" {}

		widget = {
			parentanchor = top|right

			block "tenet_badges_layout"
			{
				size = { 25 50 }
			}

			vbox = {
				container_tenet_divergence = {}
				container_tenet_popularity = {}
				expand = {}
			}
		}

		block "divergence_text" {
			icon = {
				visible = "[And( TenetType.IsValid, Not( Faith.GetMainRite.HasTenet( TenetType.Self ) ) )]"
				parentanchor = bottom|hcenter
				position = { 0 5 }
				size = { 25 25 }

				icon = {
					parentanchor = center
					size = { 20 20 }

					texture = "gfx/interface/icons/icon_rite_divergence.dds"
					tooltip = "RITE_CREATION_TENET_DIVERGENCE_TT"
				}
			}
		}
	}

